[93963] = {"À la découverte de l’Alliance", {"Allez trouver Randal Emerson au donjon de Hurlevent afin de recevoir de nouvelles instructions. Suivez ses indications pour retrouver le roi Magni Barbe-de-Bronze, le Grand Bricoleur Mekkanivelle et Tyrande Murmevent, puis entretenez-vous avec chacun d’eux."}},
[94003] = {"Le Rempart de Briseciel", {"Reprenez le Rempart des Briseciel à Zaal Pare-tempête au sanctuaire d’Akir."}},
[94006] = {"Le grand esprit ursera", {"Parlez avec Urs’endris près de la cascade au nord-est de Valanaar."}},
[94013] = {"Dompter la bête", {"Utilisez le bâtonnet de domptage pour dompter une alpha vuldrène des plaines Aérelles. Entraînez-vous à combattre à ses côtés, puis rapportez le bâtonnet de domptage à Quel’ana Vent-Vif à Valanaar."}},
[94050] = {"Entraîner la bête", {"Parlez à Quel’dora Vent-Vif à Valanaar."}},
[94369] = {"Le destin de Zéphras", {"Parlez à Talaanis Chantelombre à Valanaar."}},
[94373] = {"L’appel de la terre", {"Apportez 2 pendentifs d’ours crins-de-givre à Teo Martel-tempête, à Courbenclume."}},
[94374] = {"L’appel de la terre", {"Trouvez la pierre d’esprit et buvez le sapta de terre."}},
[94375] = {"L’appel de la terre", {"Apportez le quartz brut à Teo Martel-tempête, à Courbenclume."}},
[94411] = {"Des mages perturbateurs", {"Tuez 6 apprentis de l’Ordre suprême dans les hautes-terres de Shen’dar."}},
[94413] = {"Un affront magique", {"Tuez 6 voyants novices des Sculpte-vents dans les hautes-terres de Shen’dar."}},
[94414] = {"Les ancres de Zéphras", {"Parlez à Halaan Œil-de-Faucon et empruntez son don pour observer le pylône d’ancrage au loin."}},
[94427] = {"Une leçon de divinité", {"Parlez à Tanis Aulnebois, à Fossoyeuse."}},
[94449] = {"L’appel du feu", {"Trouvez Bruegs Flammené en Dun Morogh."}},
[94472] = {"Le sapta de terre", nil},
[94484] = {"Un silence angoissant", {"Trouvez Elegael Piquepatte dans la partie nord-est de la forêt de Trombenoire et parlez-lui."}},
[94485] = {"Les larmes de la Dame", {"Récupérez 8 morceaux de mousse des larmes de la Dame."}},
[94486] = {"Des plumes pour le bandage", {"Collectez 20 plumes sur des criailleuses trombenoire dans la forêt de Trombenoire."}},
[94487] = {"Indignes même dans la mort", {"Collectez 10 possessions ensanglantées sur des fantassins al’aketh et des chasse-tempêtes al’aketh dans la forêt de Trombenoire."}},
[94488] = {"Ces liens qui nous entravent", {"Tuez le commandant Haalien et apportez sa tête à Elegael Piquepatte dans la forêt de Trombenoire."}},
[94489] = {"La douleur de la trahison", {"Entrez dans la tanière de la Noctegriffe et soignez 7 druides, puis trouvez Jorel Chantelevent dans la forêt de Trombenoire."}},
[94490] = {"Missive déchirée", {"Apportez la missive déchirée à Elegael Piquepatte dans la forêt de Trombenoire."}},
[94491] = {"Le sort des druides", {"Apportez la missive à Lotheluum, à Valanaar, et informez-le de la situation."}},
[94568] = {"Le véritable objectif de la secte", {"Parlez à Talaanis Chantelombre et assistez à la conversation."}},
[94638] = {"Force et clémence", {"Trouvez Ur’endra dans les hautes-terres de Shen’dar et tuez-la."}},
[94774] = {"Grâce divine", {"Parlez à la grande prêtresse Laurena à Hurlevent."}},
[94896] = {"Un coup de main pour les réfugiés", {"Récupérez 8 effets abandonnés dans les ruines de Ban’aethal."}},
[94897] = {"Le sort de l’être aimé", {"Trouvez Resaan dans les ruines de Ban’aethal."}},
[94911] = {"Enfant de la nature", {"Parlez à Turak Totem-Runique aux Pitons du Tonnerre."}},
[94978] = {"Dompter la bête", {"Utilisez le bâtonnet de domptage pour dompter un clampant chantevent près d’un point d’eau.","Entraînez-vous à combattre à ses côtés, puis rapportez le bâtonnet de domptage à Quel’ana Vent-Vif à Valanaar."}},
[94979] = {"Dompter la bête", {"Utilisez le bâtonnet de domptage pour dompter un trotteur des trombes hargneux des plaines Aérelles.","Entraînez-vous à combattre à ses côtés, puis rapportez le bâtonnet de domptage à Quel’ana Vent-Vif à Valanaar."}},
[95041] = {"Amasseurs de données", {"Récupérez 7 cartes de données des archives de Gnomeregan aux alentours de Gnomeregan, puis rapportez-les à Jemma Coupecircuit à Forgefer."}},
[95065] = {"L’heure de la pêche", nil},
[95161] = {"N’oublie pas que je t’aime", {"Remettez la lettre tachée de sang à Avette Boichu dans le bois de la Pénombre."}},
[95212] = {"Il ne faut jamais s’asseoir sur la qualité", {"Récupérez 6 fourrures de léopard en parfait état et rapportez-les à la ferme des Distillambre."}},
[95213] = {"Poudre explosive volée", {"Rapportez le baril de poudre vide au responsable Thesten à la carrière de Gol’Bolar."}},
[95214] = {"Poudre explosive volée", {"Récupérez 16 tas de poudre explosive volés sur les Troggs à l’est de la carrière de Gol’Bolar, puis retournez voir le responsable Thesten."}},
[95216] = {"La peste nouvelle", {"Récupérez la souche hautement toxique auprès de Croc-Flétri dans les ruines de Lordaeron, pour Theodore Griffs, à Fossoyeuse."}},
[95217] = {"Le forgeron de la carrière", {"Récupérez 12 barres de cuivre et 4 peaux de sanglier cuirassées, puis apportez-les à Frast Dokner."}},
[95314] = {"Cet élixir vert d’Ombreval", {"Récupérez 8 bouteilles d’élixir des murmures à Ombreval, puis retournez voir Carolai Anise à Brill."}},
[95328] = {"Résidu d’horreur murmurante", {"Rapportez le résidu d’horreur murmurante au père Lankester dans le Quartier de la Guerre de Fossoyeuse."}},
[95349] = {"Le Cercle terrestre", {"Embarquez à bord d’un perceciel au départ de l’île de Zéphras pour vous rendre en Mulgore, puis parlez à Alana Marchetempête à votre arrivée."}},
[95350] = {"Bienvenue sur Azeroth", {"Voyagez jusqu’à Orgrimmar et parlez à Thrall dans la vallée de la Sagesse."}},
[95494] = {"Fierté meurtrie et peaux de lion", {"Récupérez 6 peaux de lion des savanes sur les matriarches des savanes et les patriarches des savanes dans les Tarides."}},
[95495] = {"L’ermite tanneur", {"Apportez le tas de peaux à l’ermite vivant sur la crête qui surplombe les collines Arides dans les Tarides."}},
[95507] = {"Le gibier de Vrang", {"Récupérez 8 gibiers piégés dans les pièges déclenchés un peu partout dans les Tarides."}},
[95621] = {"Des problèmes dans la vallée", {"Rendez-vous jusqu’à l’épave de la caravane et apprenez-en davantage sur les raisons de la venue des Kultirassiens."}},
[95646] = {"Horreurs dans les hautes-terres", {"Tuez une horreur des hautes-terres dans les excavations et rapportez son cœur-racine à Rethiel le Gardien vert dans les Paluns."}},
[95647] = {"Perdu dans les fourrés", {"Trouver Ardin Grassman dans les excavations"}},
[95772] = {"À la recherche de Lame-chantante", {"Cherchez Daewyn, le frère de Dorin Lame-chantante, dans les Excavations de Whelgar."}},
[95774] = {"Son nom est Olgra", {"Tuez des Hurans et récupérez 4 parures d’Olgra pour le mémorial de Mankrik."}},
[95803] = {"Un gage de bonne volonté", {"Apportez la tête de Rudolph Gelhardt à Sylvanas Coursevent, à Fossoyeuse."}},
[95805] = {"Grâce d’An’she et Mu’sha", {"Portez l’encens fumant jusqu’au sanctuaire de An’she et de Mu’sha, dans les collines au sud-est. Vous avez dix minutes avant que l’encens ne soit réduit en cendres !"}},
[95981] = {"Routes sous surveillance", {"Tuez 8 sorciers de Dalaran et 8 guetteurs de Dalaran pour le prêtre des ombres Allister au Sépulcre."}},
[95998] = {"Les grands espaces sauvages", {"Asseyez-vous près du feu de camp basique de Sam et attendez de recevoir l’amélioration Repos amplifié."}},
[95999] = {"AVIS DE RECHERCHE : incinérateur Gar’im", {"Apportez le bâton brisé de l’incinérateur Gar’im au magistrat Salomon à Comté-du-Lac."}},
[96044] = {"Introduction au camping : la forge", {"Parlez à Tognus Flammesilex, à Kharanos, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main."}},
