[96821] = {"Toutes pattes dehors", {"Tuez 6 rampantes noirecrêtes et 6 rôdeuses noirecrêtes dans le sud de Durotar, puis informez-en Gar’thok à Tranchecolline."}},
[96822] = {"Pour l’honneur", {"Récupérez la hache d’armes d’écumeur, l’arc d’écumeur et le bouclier d’écumeur aux alentours du donjon de Tiragarde, puis rapportez-les à Turroc à Tranchecolline."}},
[96825] = {"Ces fruits pourraient se défendre", {"Le cuisinier Torka de Tranchecolline souhaite que vous ramassiez 8 figues de Barbarie dans les terres des Tranchecrins à l’ouest de la ville."}},
[96874] = {"Spinal Hache", {"Ug’thok d’Orgrimmar souhaite que vous récupériez 5 échines défraîchies sur les bêtes des falaises du Tonnerre, en plus de 5 silex à aiguiser brutes."}},
[96875] = {"Les bêtes des falaises du Tonnerre", {"Kamari d’Orgrimmar souhaite que vous récupériez 5 peaux de lézard rugueuses sur les bêtes des falaises du <name>, ainsi que 2 peaux légères traitées."}},
[96876] = {"Le sac perdu d’Ukor", {"Rapportez son sac à Ukor dans le sud de Durotar."}},
[96877] = {"Le sabot d’Halikor", {"Rapportez le sabot d’Halikor à Orgrimmar."}},
[96895] = {"L’émissaire de l’Aube d’argent", {"Trouvez le membre de l’Aube d’argent près de l’entrée de Fossoyeuse."}},
[96896] = {"Une juste cause", {"Assistez à la conversation entre Danitha Morr et Leonid Barthalomew le Révéré."}},
[96897] = {"Le Culte des damnés", {"Tuez 8 néophytes sombres et 8 massacreurs sombres dans les clairières de Tirisfal."}},
[96898] = {"Les vestiges de la guerre", {"Rassemblez 12 fragments de cristal nécrotique dans les clairières de Tirisfal."}},
[96899] = {"La forteresse de Bandarion", {"Retrouvez Leonid Barthalomew à la forteresse de Bandarion, dans les clairières de Tirisfal."}},
[97003] = {"Chol’aruk le Vorace", {"Rapportez la tête de Chol’aruk à Gur’ak dans les Tarides."}},
[97223] = {"La matriarche griffesang", {"Apportez les œufs de la matriarche griffesang à Xar’Ti, au village de Sen’jin."}},
