[97236] = {"Crochet de Githyiss", {"Apportez le crochet de Githyiss à quelqu’un d’Aldrassil qui s’intéresse tout particulièrement à l’étude des araignées."}},
[97242] = {"Le mélange de Yelmak", {"Prélevez des spécimens d’herbe polisson et de roseau qui poussent près des eaux de la vallée de l’Honneur et retournez voir Kor’geld à la boutique Alchimie et potions de Yelmak."}},
[97246] = {"En souffrance de pitance", {"Allez à la Fosse à feu de Borstan et dites à ce dernier que Thatog vous demande d’apporter son déjeuner à Migi."}},
[97249] = {"Son plat préféré", {"Apportez son repas à Migi derrière le fort Grommash."}},
[97250] = {"Accusé à tort, corrigé à raison", {"Tuez des soldats de l’Alliance qui empiètent sur les Tarides, à la frontière du marécage d’Âprefange. Puis retournez voir le grunt Logmar, au camp Taurajo."}},
[97253] = {"Foire à la ferraille", {"Récupérez 5 poignées de pièces complexes au camp des pirates, au sud de Cabestan, puis retournez voir Wrenix le Misérable, à Cabestan."}},
[97263] = {"Votre paquet est arrivé", {"Apportez le paquet égaré à Eldrun."}},
[97275] = {"Droit au Whuut", {"Apportez la potion de Yelmak à Whuut."}},
[97277] = {"Grund et Gozwin", {"Trouvez le camp de Grund et Gozwin dans les collines du nord-ouest. Récupérez le journal de mécano de Gozwin et tuez le léopard des neiges rôdeur."}},
[97279] = {"Armes égarées", {"Récupérez 6 armes d’entraînement abandonnées, puis retournez auprès de Kzan Trancheronce, dans l’Antre."}},
[97281] = {"Une tempête en approche", {"Apportez l’orbe de tempête émoussé à Rezlak, près du ravin Asséché."}},
[97282] = {"Un potentiel houleux", {"Apportez 5 organes de lézard-tonnerre chargés à Rezlak, près du ravin Asséché."}},
[97288] = {"Tourment interminable", {"Remettez la tête abominable à quelqu’un, à Fossoyeuse."}},
[97326] = {"Ameublement rocheux", {"Rapportez 8 rochers lisses à Thra derrière le fort Grommash."}},
[97485] = {"Traditions des pitons", {"Achetez un paquet d’herbes à Nida l’herboriste, un fagot de brindilles de cèdre à Nata la fournisseuse de composants d’enchantements, des fibres tendineuses à Mahu le fournisseur de matériel de travail du cuir, ainsi que du silex et de l’amadou de cérémonie à Naal le fournisseur de matériel de cuisine.","","Combinez ces composants, puis répandez l’encens depuis la cime des Chasseurs."}},
[97558] = {"Des peaux pour les Réprouvés", {"Apportez à Shelene Rhobart 8 membranes d’ailes de chauve-souris de la pénombre, 6 peaux de sombredogue et 3 peaux de Murloc aileron noir."}},
[97891] = {"Livraison de potion express", {"Apportez la potion instable au docteur Martin Felben, à l’Apothicarium, avant la fin du temps imparti."}},
[97894] = {"Affaires à Auberdine", {"Prenez des nouvelles de Gorbold Main-d’acier à Auberdine, à Sombrivage.","","Borgus a parlé d’un bateau, au quai le plus au sud du port de Hurlevent, qui peut vous y emmener."}},
