[97977] = {"L’appel de la nature", {"Récupérez 4 totems pins-tordus et apportez-les à Tarindrella."}},
[97979] = {"La déesse pourvoyeuse", {"Lancez Lumière d’Elune et Camouflage dans l’ombre."}},
[98021] = {"En route pour la colline des Sentinelles", {"Allez voir Gryan Roidemantel à la colline des Sentinelles, dans la marche de l’Ouest."}},
[98024] = {"Un voyage à la Croisée", {"Faites votre rapport à Thork à la Croisée, dans les Tarides."}},
[98025] = {"ON RECHERCHE : Jai’vhanel", {"Trouvez Jai’vhanel et terrassez-la, puis récupérez l’une de ses plumes. La chouette noire a été aperçue pour la dernière fois au nord des ruines d’Ameth’Aran, près du pied de la montagne. Signalez la mort de Jai’vhanel à la sentinelle Glynda Nal’Shea, à Auberdine."}},
[98067] = {"Regard des Sentinelles", {"Placez des hiboux sentinelles à l’entrée des profondeurs du fort Cénarien, à la banque de Darnassus, à l’auberge de la terrasse des Artisans et aux portes de la ville pour la sentinelle Dalia Lamesoleil au temple de la Lune, à Darnassus."}},
[98189] = {"Rapporter la statuette", {"Apportez la statuette de Menethil au capitaine Rudepoing, au donjon de Menethil."}},
[98197] = {"Butin de guerre", {"Récupérez 6 morceaux de bois de construction de Khaz Modan et 30 unités de fer de Khaz Modan au port de Menethil pour Valstag Gueule-de-fer."}},
[98208] = {"Fleur des cieux", {"Récupérez Nord’el pour Sylessa Murmesoir, au port de Menethil."}},
[98209] = {"Fleur des cieux", {"Apportez Nord’el à Thundris Tissevent à Auberdine, en Sombrivage.","","Sylessa vous a parlé d’un bateau qui peut vous y conduire en partant du port de Menethil."}},
[98216] = {"Comprendre notre présent", {"Utilisez la pierre de Goaz près du gardien de Goaz, puis rapportez sa pierre-clé titanesque au prospecteur Whelgar."}},
[98221] = {"Tiré des cendres", {"Le capitaine Rudepoing du donjon de Menethil vous demande de détruire 4 plans d’attaque dans le campement de Hargnecroc."}},
[98245] = {"Travail d’aiguille tranchegueule", {"Obtenez 10 incisives de tranchegueule pour Howin Genteplume."}},
[98246] = {"Période de disette", {"Obtenez 12 œufs de tranchegueule en parfait état pour Howin Genteplume."}},
[98247] = {"Étiquette d’envoi", {"Apportez l’étiquette d’envoi au personnel du poste de l’Administration commerciale d’Azeroth dans les Carmines."}},
[98248] = {"Étiquette d’envoi", {"Apportez l’étiquette d’envoi au personnel du poste des Transports logistiques Durotar près de la Croisée dans les Tarides."}},
[98282] = {"Dangers alchimiques", {"Procurez-vous une glande de traqueur intacte au rocher de Thelgen, et apportez-la à Caitlin Grassman, au port de Menethil."}},
[98283] = {"Carnage", {"Apportez la tête de Carnage à Rethiel le Gardien vert, dans la Ceinture verte."}},
[98284] = {"Introduction au camping : l’enchantement", {"Parlez à Nasalanna Chantelevent, à Shen’dar, pour apprendre à fabriquer un objet de camping propre à votre métier une fois que vous vous serez fait la main."}},
