[98291] = {"Mort aux Gueules-de-Dragon", {"Tuez 8 récupérateurs gueules-de-dragon, 5 lieurs d’âme gueules-de-dragon et 3 infitrateurs gueules-de-dragon dans la retraite des Gueules-de-dragon afin d’aider Howin Genteplume."}},
[98293] = {"Désarmement forcé", {"Récupérez 30 armes gueules-de-dragon dans la retraite des Gueules-de-dragon, puis apportez-les au capitaine Rudepoing, au donjon de Menethil."}},
[98298] = {"La folie d’Arugal", {"Rapportez 6 morceaux worgens à Dalar Tisselaube au Sépulcre."}},
[98299] = {"Endiguer la propagation", {"Tuez 5 réfugiés malades et 5 réfugiés hagards pour Dalar Tisselaube au Sépulcre."}},
[98319] = {"Sécuriser la montagne", {"Trouvez le montagnard Cornélius dans l’antre Gris pour la montagnarde Gretchen."}},
[98321] = {"Cargaison de Flammesilex", {"Récupérez 8 cargaisons de Flammesilex à l’antre Gris pour Tongus Flammesilex, à Kharanos."}},
[98322] = {"Sécuriser la montagne", {"Allez voir la montagnarde Gretchen à l’ouest de Kharanos."}},
[98323] = {"Sécuriser la montagne", {"Apportez le rapport de la montagnarde Gretchen à Senir Blanchebarbe, à Kharanos."}},
[98326] = {"Hurlegivre", {"Éliminez Hurlegivre et récupérez le sac de poissons de Gretta Ganter, à Brassetout."}},
[98389] = {"Une lumière dans les ténèbres", {"Libérez 6 victimes entoilées dans la grotte des tisse-nuit pour Aramis Mainmartel, au Glas."}},
[98391] = {"La Sororité d’Élune", {"Parlez à Sœur Aquinne à Darnassus."}},
[98392] = {"Les ténèbres dans la clairière", {"Récupérez l’amulette de Hurlehaine, l’amulette de la maîtresse des vents Gaedress et l’amulette de la mère sorcière Arysa, puis rapportez-les à la sentinelle Arynia Éclairciel dans la clairière de l’Oracle."}},
[98398] = {"L’arbre de l’Oracle", {"Trouvez l’écorce de l’arbre de l’Oracle dans les environs afin de recevoir son message."}},
[98403] = {"Haine folle", {"Tuez 8 tissebois souillées et rapportez la gangremousse mûre de Xethorr le Malfaisant à Tallonkai Viveracine, à Dolanaar."}},
[98407] = {"Démonstration de force", {"Récupérez 5 colliers cloutés sur des vandales gnolls pour l’adjoint Feldon, près de Comté-du-Lac."}},
[98423] = {"Le traité d’entente", {"Remettez le traité de l’entente à Magni Barbe-de-Bronze, à Forgefer."}},
[98424] = {"Les notes de Vibrouage", {"Récupérez les pages du superviseur Vibrouage se trouvant encore à l’intérieur de la mine de la KapitalRisk, et apportez-les à Morin Traqueur-de-Nuage, près de Sabot-de-Sang."}},
[98427] = {"Fin des opérations", {"Apportez la clé de déboiseur à Morin Traqueur-de-Nuage, à l’extérieur de Sabot-de-Sang."}},
[98430] = {"Les longues-marches", {"Aidez Périth Sabot-tempête à fuir le rocher des Crins-pâles, et allez aux Pitons-du-Tonnerre pour informer Cairne Sabot-de-Sang que Périth est sain et sauf."}},
[98435] = {"Rapport de Corne-Tonnerre", {"Apportez le rapport de Corne-Tonnerre à l’archidruide Hamuul Totem-Runique, aux Pitons-du-Tonnerre."}},
[98461] = {"Amour non partagé", {"Apportez la note de Hollee à Tarrel Tisseroche près du port de Menethil, dans les Paluns."}},
[98512] = {"Les assassins al’aketh", {"Tuez 10 assassins al’aketh dans les hautes-terres de Shen’dar."}},
[98545] = {"La lettre de Leonid", {"Portez la lettre scellée à Glix Xizzix à Fossoyeuse."}},
[98581] = {"La rune archaïque", {"Lisez la rune archaïque, puis parlez à Teo Martel-tempête, à Courbenclume."}},
[98601] = {"Un chemin tortueux", {"Lisez le parchemin consacré et parlez à Aramis Mainmartel, dans l’église du Glas."}},
[98815] = {"Cuir des hautes-terres", {"Rapportez 4 peaux de raptor des fourrés à James Halloran, le tanneur, au port de Menethil."}},
[99046] = {"La messagère égarée", {"Partez à la recherche de la sentinelle Eralya Feuillombre sur la route menant à la clairière de l’Oracle."}},
[99047] = {"Toujours en vie", {"Allez chercher l’aide de Byancie à Dolanaar pour la sentinelle Eralya Feuillombre."}},
[99048] = {"Une main en moins", {"Trouvez Heglan Ombredœil au nord du donjon de Tiragarde."}},
[99049] = {"Une menace venue d’en bas", {"Trouvez des traces de ce qui a attaqué Heglan Ombredœil."}},
[99050] = {"La bonté du Grand arbre", {"Récupérez 6 frondes de flagellant humide, une fiole vide et de l’eau de source pour Byancie à Dolanaar."}},
[99051] = {"Une menace venue d’en bas", {"Récupérez 9 ailerons épineux de Nagas."}},
[99052] = {"Une menace venue d’en bas", {"Tuez le Géant des mers au large de la côte nord de Durotar, puis rapportez une preuve de votre victoire."}},
[99053] = {"Évasion de Ban’ethil", {"Aidez la sentinelle Lynessa Floraisombre à s’échapper du Refuge des saisons de Ban’ethil et escortez-la jusqu’à la sentinelle Kyra Chantétoile à Dolanaar."}},
[99079] = {"Longue-marche Malah", {"Trouvez la longue-marche Malah Longuebrise à l’est de Sabot-de-Sang, près de la frontière de Mulgore."}},
[99080] = {"Qu’ils disparaissent", {"Tuez 6 Centaures galak et 4 estafettes galak, puis apportez la tête d’Herak le Pilleur à Baine Sabot-de-Sang."}},
[99081] = {"De sombres nouvelles", {"Apportez le rapport de la longue-marche Malah au brave Course-Sauvage à Sabot-de-Sang."}},
[99082] = {"Le grand chef", {"Sollicitez une audience auprès de Cairne Sabot-de-Sang aux Pitons-du-Tonnerre."}},
[99101] = {"Un adversaire ancien", {"Apportez le rapport de la longue-marche Malah à Baine Sabot-de-Sang."}},
[99108] = {"Combat d’entraînement", {"Battez 3 autres personnages-joueurs en duel ou guerriers novices pour Tang Sabot-de-Pierre."}},
[99123] = {"Perdue dans les ombres", {"Aidez Pal’juh à sortir de la combe des Kolkar, puis informez-en maître Vornal, au village de Sen’jin."}},
[99127] = {"Filet sans arêtes", {"Jetez un œil aux pièges à poissons dans le lac de Cristal."}},
[99128] = {"Menace visqueuse", {"Tuez 7 Murlocs et 4 ruisseliers murlocs au lac de Cristal, puis retournez voir Jason Mathers."}},
[99129] = {"Solution anti-Murloc", {"Parlez du problème de Murlocs de Jason à Remy « Deux fois »."}},
[99130] = {"Une proposition alléchante", {"Rassemblez les ingrédients pour l’appât à Murloc."}},
[99131] = {"Appâter pour mieux tuer", {"Retournez voir Jason Mathers."}},
[99134] = {"Discipline", {"Punissez 5 nécrogardes pour l’exécuteur Zygand."}},
[99141] = {"Patience", {"Obtenez les rapports des nécrogardes Dillinger et Kristof et de Gordo pour l’exécuteur Zygand."}},
[99142] = {"Herbes sépulcrales", {"Récoltez 5 herbes sépulcrales et apportez-les à l’apprenti apothicaire Holland."}},
[99143] = {"Appâts de pacotille", {"Récupérez 6 morceaux de camelote rutilante dans le camp murloc voisin."}},
[99144] = {"Demande d’asile", {"Aidez Bareth Pierre-d’Aube à fuir l’avant-poste des Croisés, puis allez à Brill pour informer Shari Morpuits que Bareth est sain et sauf."}},
[99152] = {"L’ombre sous le val", {"Rassemblez 6 os faiblement luminescents pour Hilda la Briseuse."}},
[99153] = {"Celui qui s’échappa", {"Trouvez le fragment de cristal caché sous Ombreval pour Ephram Barbaro."}},
[99156] = {"Patrouille d’arrière-garde", {"Apportez le cœur de Fendécorche à la nécrogarde Linnea."}},
[99158] = {"Aube sur les montagnes", {"Apportez la caisse de bougies au père Gavin, au refuge de Brumepins."}},
[99159] = {"Un peu de chaleur", {"Rassemblez 14 morceaux de petit bois."}},
[99160] = {"La colère du givre", {"Détruisez 10 élémentaires de glace mineurs."}},
[99161] = {"La colère du givre", {"Tuez Avala et récupérez son noyau."}},
[99162] = {"Un froid dangereux", {"Récupérez les fusils des montagnards disparus."}},
[99196] = {"Un don de laine", nil},
[99260] = {"La mission de Fillion", {"Parlez à Elaadrin Trombecalme, à Valanaar."}},
[99411] = {"Kyle a disparu !", {"Ahab Sabot-de-Blé, à Sabot-de-Sang en Mulgore, veut que vous nourrissiez son précieux chiot, Kyle le Frénétique.","","Donnez de la Viande de trotteur tendre à Kyle puis retournez voir Ahab Sabot-de-Blé."}},
}]])
